<td data-label="Item" class="border-b border-slate-100 px-1.5 py-1.5 text-center"><span data-item-number class="text-[11px] font-semibold text-slate-500">{{ is_numeric($index) ? $index + 1 : '' }}</span></td>
<td data-label="Kategori" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Kategori" list="po-categories" data-po-category name="items[{{ $index }}][category]" value="{{ old('items.'.$index.'.category', $item['category'] ?? '') }}" required placeholder="Pakaian" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Sub-kategori" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Sub-kategori" list="po-sub-categories" data-po-sub-category name="items[{{ $index }}][sub_category]" value="{{ old('items.'.$index.'.sub_category', $item['sub_category'] ?? '') }}" required disabled placeholder="Pilih kategori dulu" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Produk / katalog" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Produk atau katalog" list="po-products" data-po-product name="items[{{ $index }}][product_name]" value="{{ old('items.'.$index.'.product_name', $item['product_name'] ?? '') }}" required disabled placeholder="Pilih kategori dulu" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Model / motif" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Model atau motif" list="po-models" name="items[{{ $index }}][model]" value="{{ old('items.'.$index.'.model', $item['model'] ?? '') }}" required disabled placeholder="Pilih kategori dulu" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Ukuran" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Ukuran" list="po-sizes" name="items[{{ $index }}][size]" value="{{ old('items.'.$index.'.size', $item['size'] ?? '') }}" required disabled placeholder="Pilih kategori dulu" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Warna" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Warna" list="po-colors" name="items[{{ $index }}][color]" value="{{ old('items.'.$index.'.color', $item['color'] ?? '') }}" required disabled placeholder="Pilih kategori dulu" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Jenis kain" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Jenis kain" list="po-fabrics" name="items[{{ $index }}][fabric_name]" value="{{ old('items.'.$index.'.fabric_name', $item['fabric_name'] ?? '') }}" placeholder="Cotton" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Kebutuhan kain yard/kg" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Kebutuhan kain yard atau kilogram" name="items[{{ $index }}][yard_kg]" type="number" min="0.01" step="0.01" value="{{ old('items.'.$index.'.yard_kg', $item['yard_kg'] ?? '') }}" required placeholder="250" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Rib" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Jumlah rib" name="items[{{ $index }}][rib_qty]" type="number" min="0" step="0.01" value="{{ old('items.'.$index.'.rib_qty', $item['rib_qty'] ?? '') }}" placeholder="0" class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Rasio yard/pcs" class="border-b border-slate-100 px-1 py-1.5"><input aria-label="Rasio kain per pcs" name="items[{{ $index }}][ratio]" type="number" min="0.0001" step="0.0001" value="{{ old('items.'.$index.'.ratio', $item['ratio'] ?? '0.25') }}" required class="!min-w-0 !rounded-md !px-1.5 !py-1.5 !text-[11px]"></td>
<td data-label="Estimasi hasil" class="whitespace-nowrap border-b border-slate-100 px-1.5 py-1.5 text-right"><output data-ratio-result class="text-[11px] font-bold text-slate-800">— pcs</output></td>
<td data-label="Aksi" class="border-b border-slate-100 px-1 py-1.5 text-center"><button type="button" data-remove-item aria-label="Hapus item PO" class="rounded-md px-1.5 py-1 text-[10px] font-semibold text-rose-600 hover:bg-rose-50">Hapus</button></td>
